SET check_function_bodies=off;
SET timezone='America/Sao_Paulo';
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE SCHEMA lts_award_private;
CREATE TABLE public.legacy_namespace(id bigint GENERATED BY DEFAULT AS IDENTITY,usuario_id uuid,chave text,valor_bruto text,sha256 text,UNIQUE(usuario_id,chave));
CREATE TABLE public.app_settings(user_id uuid PRIMARY KEY,settings jsonb,updated_at timestamptz DEFAULT now());
CREATE TABLE public.lts_future_liquidity_schedule(
 id text PRIMARY KEY,user_id uuid,source_asset_id text,asset_type text,institution text,
 eligibility_date date,settlement_days integer,quantity numeric,unit_price_assumption numeric,fx_assumption numeric,
 gross_value_brl numeric,net_value_brl numeric,tax_status text,cash_treatment text,confidence text,source text,
 metadata jsonb,active boolean,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.asset_positions(id uuid DEFAULT gen_random_uuid(),user_id uuid,legacy_id text,asset_type text,asset_name text,
 as_of_date date,quantity numeric,unit_price numeric,fx_rate numeric,value_brl numeric,liquidity_class text,
 is_available_now boolean,availability_note text,metadata jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE public.lts_brokerage_position_snapshots(id uuid DEFAULT gen_random_uuid(),user_id uuid,institution text,as_of_date date,
 currency text,total_gross_brl numeric,available_total_brl numeric,unavailable_total_brl numeric,
 vested_shares_available_brl numeric,brokerage_cash_available_brl numeric,future_rsu_gross_brl numeric,
 future_cash_rsu_gross_brl numeric,vested_share_quantity numeric,future_rsu_quantity numeric,future_cash_rsu_quantity numeric,
 source text,source_label text,metadata jsonb,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),
 other_available_brl numeric DEFAULT 0,other_unavailable_brl numeric DEFAULT 0);
CREATE TABLE public.evento_base(id bigint GENERATED BY DEFAULT AS IDENTITY,usuario_id uuid,idx integer,dados jsonb);
CREATE TABLE public.financial_events(id uuid DEFAULT gen_random_uuid(),user_id uuid,event_date date,amount numeric,metadata jsonb);
CREATE TABLE public.accounts(user_id uuid,is_active boolean,metadata jsonb);
CREATE TABLE public.fgts(usuario_id uuid,dados jsonb);
CREATE TABLE public.audit_log(id bigint GENERATED BY DEFAULT AS IDENTITY,user_id uuid,action text,entity_type text,entity_id text,details jsonb);
CREATE TABLE public.lts_product_read_cache(user_id uuid PRIMARY KEY,payload jsonb);
CREATE TABLE public.lts_dashboard_cockpit_cache(user_id uuid PRIMARY KEY,payload jsonb);
CREATE TABLE public.lts_flow_future_read_cache(user_id uuid);
CREATE TABLE public.lts_flow_future_read_cache_v2(user_id uuid);
CREATE TABLE public.lts_v229_read_cache(user_id uuid,kind text,payload jsonb);
CREATE TABLE public.lts_read_cache_epoch_v242(singleton boolean PRIMARY KEY,epoch bigint);
INSERT INTO public.lts_read_cache_epoch_v242 VALUES(true,10);
CREATE TABLE public.lts_validated_lock_registry(lock_key text,canonical_value jsonb,superseded_at timestamptz);
CREATE TABLE public.qa_market_context_v411(context jsonb);
INSERT INTO public.qa_market_context_v411 VALUES('{"complete":false,"stock":{"value":10},"usd_brl":{"value":5}}');
CREATE FUNCTION public.lts_market_context_v290() RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT context FROM public.qa_market_context_v411$$;
CREATE FUNCTION public.lts_browser_assert_user_v1() RETURNS uuid LANGUAGE plpgsql STABLE AS $$
DECLARE u uuid:=nullif(current_setting('test.user_id',true),'')::uuid;BEGIN IF u IS NULL THEN RAISE EXCEPTION 'authentication required';END IF;RETURN u;END$$;
CREATE FUNCTION public.lts_corrected_cashflow_v1(uuid,date,date) RETURNS TABLE(event_date date,signed_amount numeric)
 LANGUAGE sql AS $$SELECT $2,0::numeric$$;
CREATE FUNCTION public.lts_corrected_cashflow_fix86_v4(uuid,date,date) RETURNS TABLE(event_date date,signed_amount numeric,description text)
 LANGUAGE sql AS $$SELECT $2,0::numeric,''::text WHERE false$$;
CREATE FUNCTION public.lts_payroll_withholding_effective_v1(uuid,date,date) RETURNS TABLE(effective_event_date date,amount numeric)
 LANGUAGE sql AS $$SELECT $2,0::numeric WHERE false$$;
CREATE FUNCTION public.lts_daily_flow_fix86_v14(uuid,date,date) RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('days',jsonb_agg(jsonb_build_object('date',d::date,'fix86_columns',
  jsonb_build_object('saldo_final',0,'liq_d0_1_recurso',0,'saldo_apos_rsu',0,'saldo_apos_fgts',0,'fgts',0,'rsus_vested',0))),
  'events','[]'::jsonb) FROM generate_series($2,$3,interval '1 day')d$$;
CREATE FUNCTION public.lts_daily_flow_fix86_v13(uuid,date,date) RETURNS jsonb LANGUAGE sql AS $$SELECT public.lts_daily_flow_fix86_v14($1,$2,$3)$$;
CREATE FUNCTION public.lts_open_finance_current_bank_position_v1(uuid) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"bank_cash":0}'::jsonb$$;
CREATE FUNCTION public.lts_cofrinho_effective_locked_v245(uuid,date) RETURNS numeric LANGUAGE sql AS $$SELECT 0::numeric$$;
CREATE FUNCTION public.lts_cofrinho_effective_series_v399(uuid,date,date) RETURNS TABLE(flow_date date,effective_value_brl numeric)
 LANGUAGE sql AS $$SELECT d::date,0::numeric FROM generate_series($2,$3,interval '1 day')d$$;
CREATE FUNCTION public.lts_asset_position_effective_v1(uuid,date) RETURNS TABLE(asset_type text,effective_value_brl numeric,documented_as_of date,asset_position_id uuid)
 LANGUAGE sql AS $$SELECT 'FGTS'::text,0::numeric,$2,'00000000-0000-4000-8000-000000000099'::uuid$$;
CREATE FUNCTION public.lts_dashboard_cash_ladder_from_flow_v1(uuid,date,date,jsonb)
 RETURNS TABLE(flow_date date,operational_cash numeric,d01_resource numeric,balance_after_d01 numeric,rsu_vested_today numeric,rsu_vested_scheduled numeric,balance_no_new_vesting numeric,balance_with_scheduled_vesting numeric,fgts_projected numeric,balance_with_fgts_projected numeric)
 LANGUAGE sql AS $$SELECT * FROM public.lts_dashboard_cash_ladder_from_flow_v229($1,$2,$3,$4)$$;
CREATE FUNCTION public.lts_dashboard_cash_ladder_v1(uuid,date,date)
 RETURNS TABLE(flow_date date,operational_cash numeric,d01_resource numeric,balance_after_d01 numeric,rsu_vested_today numeric,rsu_vested_scheduled numeric,balance_no_new_vesting numeric,balance_with_scheduled_vesting numeric,fgts_projected numeric,balance_with_fgts_projected numeric)
 LANGUAGE sql AS $$SELECT * FROM public.lts_dashboard_cash_ladder_from_flow_v229($1,$2,$3,public.lts_daily_flow_fix86_v14($1,$2,$3))$$;
CREATE FUNCTION public.lts_browser_wealth_detail_v1() RETURNS jsonb LANGUAGE sql AS $$SELECT '{}'::jsonb$$;
CREATE FUNCTION public.lts_commitments_summary_v1(uuid,date) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"commitments":[]}'::jsonb$$;
CREATE FUNCTION public.lts_documentary_commitments_v1(uuid) RETURNS jsonb LANGUAGE sql AS $$SELECT '{}'::jsonb$$;
CREATE FUNCTION public.lts_fgts_position_evidence_v386(uuid,date) RETURNS jsonb LANGUAGE sql AS $$SELECT '{}'::jsonb$$;
CREATE FUNCTION public.lts_current_evidence_position_v1(uuid) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"liquidity_through_d3":0,"restricted_assets":0}'::jsonb$$;
CREATE FUNCTION public.lts_daily_flow_v69plus_v1(uuid,date,date) RETURNS jsonb LANGUAGE sql AS $$SELECT public.lts_daily_flow_fix86_v14($1,$2,$3)$$;
CREATE FUNCTION public.lts_projection_year_audit_v1(uuid,integer,integer) RETURNS jsonb LANGUAGE sql AS $$SELECT '{}'::jsonb$$;
CREATE TABLE public.qa_checks_v411(name text PRIMARY KEY,passed boolean NOT NULL);
CREATE FUNCTION public.qa_assert_v411(label text,ok boolean) RETURNS void LANGUAGE plpgsql AS $$BEGIN
 IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'V411 assertion failed: %',label;END IF;
 INSERT INTO public.qa_checks_v411 VALUES(label,true) ON CONFLICT(name)DO UPDATE SET passed=true;
END$$;
